// Splits extract-spec.cjs's single output into resolved-spec/, one file per surface, and writes its README.
// Run: node split-spec.cjs [<raw spec, default: $TMPDIR/b3e-spec.md>]
// 🔴 WRITTEN 2026-09-21 10:14 EDT because the README said "then re-split" and no script did it: the split had been done by hand, once,
// so the spec could not be regenerated by anyone but the session that made it. That is the staleness trap for Session 4, which is
// told to regenerate after any decision that changes a switch. The whole chain is now: switches.cjs → extract-spec.cjs → split-spec.cjs → measure.cjs.
const fs = require('fs'); const path = require('path');
// BOARD=4 (2026-09-21 13:38 EDT) splits Board 4: Collective's spec into ../../2026-09-21-pins2-final/board4-spec/, one file per surface C1–C10.
const B4 = process.env.BOARD === '4';
const RAW = process.argv[2] || path.join(require('os').tmpdir(), B4 ? 'b4-spec.md' : 'b3e-spec.md');
const DIR = B4 ? __dirname : path.join(__dirname, 'resolved-spec');
const BOARD_NAME = B4 ? 'Board 4: Collective' : 'Board 3-E';
if (B4) fs.mkdirSync(DIR, { recursive: true });
const raw = fs.readFileSync(RAW, 'utf8'); const lines = raw.split('\n');
const NAME = B4 ? [[/^## Tokens/, 'tokens.md'], [/^## @keyframes/, 'motion.md'], [/^## C1 /, 'C1-armory-manifest.md'], [/^## C2 /, 'C2-new-build.md'], [/^## C3 /, 'C3-compare.md'],
  [/^## C4 /, 'C4-repairs.md'], [/^## C5 /, 'C5-export.md'], [/^## C6 /, 'C6-delivery-queue.md'], [/^## C7 /, 'C7-broadcast.md'], [/^## C8 /, 'C8-history.md'],
  [/^## C9 /, 'C9-admin-traffic.md'], [/^## Reachable states/, 'states.md']] : [[/^## Tokens/, 'tokens.md'], [/^## @keyframes/, 'motion.md'], [/^## L1 /, 'L1-list-lab.md'], [/^## M1 /, 'M1-armory-manifest.md'],
  [/^## M2 /, 'M2-repairs.md'], [/^## M3 /, 'M3-export.md'], [/^## B1 /, 'B1-delivery-queue.md'], [/^## H1 /, 'H1-history.md'],
  [/^## Reachable states/, 'states.md'], [/^## P7 /, 'P7-command-search.md']];
const heads = lines.map((l, i) => [l, i]).filter(([l]) => /^## /.test(l));
const gen = (lines.find((l) => /^\*Generated /.test(l)) || '').trim();
// (2026-09-27 02:43 EDT) The extractor's "Not reached" list sat only in the raw file, so the tracked README never showed its coverage holes.
const nr = (() => { const i = lines.findIndex((l) => /^⚠️ \*\*Not reached\*\*/.test(l)); if (i < 0) return []; const out = [lines[i], '']; for (let j = i + 1; j < lines.length && !/^## /.test(lines[j]); j++) if (/^- /.test(lines[j])) out.push(lines[j]); return out.concat(['']); })();
const parts = heads.map(([h, i], n) => { const hit = NAME.find(([re]) => re.test(h)); if (!hit) throw new Error(`no file name for heading: ${h}`);
  return { file: hit[1], title: h.slice(3), body: lines.slice(i, n + 1 < heads.length ? heads[n + 1][1] : lines.length).join('\n') }; });
if (parts.length !== NAME.length) throw new Error(`expected ${NAME.length} sections, got ${parts.length}`);
for (const p of parts) fs.writeFileSync(path.join(DIR, p.file), ['---', 'kind: reference', 'status: live', '---', '',
  `# ${BOARD_NAME} resolved values · ${p.title}`, '', '*Part of the generated spec; read `README.md` in this folder first.*', '', p.body.trimEnd(), ''].join('\n'));
const readme = ['---', 'kind: reference', 'status: live', '---', '', `# ${BOARD_NAME} — the resolved values`, '', gen, '',
  ...nr,
  ...(B4 ? ['🔴 **Board 4: Collective is every finished surface of boards 1–3 on the kit\'s portal code, no switches.** Regenerate with `BOARD=4` on both scripts: `BOARD=4 node docs/pins2/final/board4-spec/extract-spec.cjs \'\' $TMPDIR/b4-spec.md` then `BOARD=4 node docs/pins2/final/board4-spec/split-spec.cjs $TMPDIR/b4-spec.md`. Read [`../FINAL.md`](../FINAL.md) first.', ''] : []),
  '**How to read a table.** *winning declaration* is the text Chrome applied for that property name — or its logical twin, shown as `(as padding-inline-start)` — in cascade order with `!important` honoured; *computed* is what it resolved to; *from* is the selector and `file:line` in the kit. ↑ means nothing on the element declares it and the value is inherited from the named ancestor rule. A percentage beside a pixel value is RESOLUTION: port the percentage. ⚠️ marks the only real conflict — two absolute lengths that disagree — and the computed column is the truth. ⏳ marks a rule keyed on a switch Session 4 still owns (p10, e1–e6): provisional, however it renders. A user-agent row is kept only where it sets something other than a default.',
  '', B4 ? '🔴 **Read [`HANDOFF.md`](HANDOFF.md) first — the authored half: per gate what it is, how it behaves and what he ruled. A `from` selector carrying `html[data-b3-…]` is SWITCHED:** read [`switches.md`](switches.md) (port a live one without the qualifier, never a dead one), then [`file-map.md`](file-map.md), [`portal-diff.md`](portal-diff.md), [`class-map.md`](class-map.md), [`token-map.md`](token-map.md) and [`portal-class-rules.md`](portal-class-rules.md) — all generated for Board 4 — before porting a single declaration.' : '🔴 **A `from` selector carrying `html[data-b3-…]` is SWITCHED.** Read [`../switches.md`](../switches.md) first: port a live one without the qualifier, never port a dead one. And read [`../token-map.md`](../token-map.md) and [`../class-map.md`](../class-map.md) before porting a single declaration — the board reads `--b3-*` and `--h1-*` tokens and 204 classes the portal does not have.',
  '', '**Regenerate** after ANY change to the kit — including Session 4 changing a switch — with the kit served on :8900 (`.claude/launch.json` → `repo-static`). **The one full command is `docs/pins2/README.md` § Regenerate the spec** (it adds motion, colours, components, hover relations, the copy inventory and the inventory); the block below is its first half:', '', '```bash',
  ...(B4 ? ['O=docs/pins2/final/board4-spec',
    'node $O/switches.cjs && node $O/overrides.cjs', 'BOARD=4 node $O/extract-spec.cjs \'\' $TMPDIR/b4-spec.md && BOARD=4 node $O/split-spec.cjs $TMPDIR/b4-spec.md', 'node $O/maps.cjs', 'node $O/copy.cjs', 'node $O/structure.cjs && node $O/relations.cjs && node $O/a11y.cjs'] :
  ['node docs/pins2/final/board4-spec/switches.cjs', 'node docs/pins2/final/board4-spec/extract-spec.cjs',
  'node docs/pins2/final/board4-spec/split-spec.cjs', 'node docs/pins2/final/board4-spec/measure.cjs']), '```', '', ...(B4 ? ['`relations.cjs` measures his rulings that are relations on the running board ([`relations.md`](relations.md)); `measure.cjs` is Board 3-E\'s, its selectors board 3\'s.', ''] : []),
  '| File | Surface | Size |', '|---|---|---|', ...(B4 ? ['| [`HANDOFF.md`](HANDOFF.md) | the authored port contract, per gate | — |', '| [`switches.md`](switches.md) · [`file-map.md`](file-map.md) · [`portal-diff.md`](portal-diff.md) · [`class-map.md`](class-map.md) · [`token-map.md`](token-map.md) · [`portal-class-rules.md`](portal-class-rules.md) | the maps, generated | — |'] : []), ...parts.map((p) => `| [\`${p.file}\`](${p.file}) | ${p.title} | ${Math.round(Buffer.byteLength(p.body) / 1024)} KB |`), ''];
fs.writeFileSync(path.join(DIR, 'README.md'), readme.join('\n'));
console.log(JSON.stringify({ files: parts.length, bytes: parts.reduce((a, p) => a + p.body.length, 0) }));
